def transform(grid):
    R, C = len(grid), len(grid[0])

    # First pass: identify which cell will "claim" which value
    # Each cell takes the color that's "closest" in terms of row/col proximity

    result = [[0]*C for _ in range(R)]

    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0:
                result[r][c] = grid[r][c]
            else:
                # Find all colored neighbors
                colored = []
                for dr in [-2, -1, 0, 1, 2]:
                    for dc in [-2, -1, 0, 1, 2]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            if grid[nr][nc] != 0:
                                colored.append(grid[nr][nc])

                # If we found colored neighbors, use the most common
                if colored:
                    from collections import Counter
                    counts = Counter(colored)
                    # Use the color with highest count, tie-break by position
                    most_common = counts.most_common(1)[0][0]
                    result[r][c] = most_common
                else:
                    result[r][c] = 2

    return result
